import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Adds each pasted amount in order to the person's opening balance for the period, recorded as
 *  OPENING_SET sheet=<id> by=<user> name=<name> period=<period> amount=<amount>. */
public class SaveOpeningImport {
    public void save(@PathVariable("sheetId") String sheetId, @Val OpeningImportInput imported, OpeningStore store,
            Audit audit, Out<OpeningImportResult> result) {
        String sheet = sheetId.trim();
        for (OpeningLine line : imported.lines()) {
            store.add(sheet, line.period(), line.person().getId(), line.amount());
            audit.record("OPENING_SET sheet=" + sheet + " by=" + imported.user() + " name=" + line.person().getName()
                    + " period=" + line.period() + " amount=" + line.amount().setScale(2).toPlainString());
        }
        result.set(new OpeningImportResult(imported.lines().size()));
    }
}
package net.officefloor.hq.app.opening;

import java.math.BigDecimal;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** Each person's opening balance for a period on each sheet. */
@Repository
public class OpeningStore {

    private final JdbcTemplate jdbc;

    public OpeningStore(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every opening balance on the sheet, by period then person. */
    public List<OpeningResponse> list(String sheetId) {
        return jdbc.query("SELECT * FROM period_person_opening WHERE sheet_id = ? ORDER BY period_name, person_id",
                (rs, i) -> new OpeningResponse(rs.getString("period_name"), rs.getLong("person_id"),
                        rs.getBigDecimal("amount").setScale(2).toPlainString()),
                sheetId);
    }

    /** Adds the amount to the person's opening balance for the period. */
    public void add(String sheetId, String periodName, long personId, BigDecimal amount) {
        if (jdbc.update("UPDATE period_person_opening SET amount = amount + ? WHERE sheet_id = ? AND period_name = ? "
                + "AND person_id = ?", amount, sheetId, periodName, personId) == 0) {
            jdbc.update("INSERT INTO period_person_opening (sheet_id, period_name, person_id, amount) VALUES (?, ?, ?, ?)",
                    sheetId, periodName, personId, amount);
        }
    }
}
package net.officefloor.hq.app.opening;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.period.PeriodResponse;
import net.officefloor.hq.app.period.PeriodStore;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonStore;
import net.officefloor.hq.app.role.RoleStore;
import net.officefloor.hq.app.sheet.InvalidSheetException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * Checks every pasted line before anything is stored. Each line is name,period,amount: the name (or an alias)
 * of a person on the sheet (ignoring case and the spaces around it), the name of a period on the sheet
 * (ignoring case) and an amount of two decimals, 0.00 or more. Blank lines are skipped; a paste with no line
 * is refused.
 */
public class ValidateOpeningImport {
    public void validate(@PathVariable("sheetId") String sheetId, @RequestBody OpeningImportRequest request,
            PersonStore people, PeriodStore periods, RoleStore roles, Out<OpeningImportInput> imported)
            throws InvalidSheetException {
        String sheet = sheetId.trim();
        String user = request == null ? null : request.user();
        roles.refuseChange(sheet, user);
        String text = request == null || request.text() == null ? "" : request.text();
        List<PeriodResponse> onSheet = periods.list(sheet);
        String[] lines = text.split("\\r?\\n");
        List<OpeningLine> openings = new ArrayList<>();
        for (int i = 0; i < lines.length; i++) {
            String line = lines[i];
            if (line.trim().isEmpty()) {
                continue;
            }
            String[] fields = line.split(",", -1);
            if (fields.length != 3) {
                throw new InvalidSheetException("Line " + (i + 1) + " must be name,period,amount");
            }
            Person person = people.findByName(sheet, fields[0]);
            if (person == null) {
                throw new InvalidSheetException("Line " + (i + 1) + ": No such person: " + fields[0].trim());
            }
            String periodName = fields[1].trim();
            PeriodResponse period = onSheet.stream().filter(p -> p.name().equalsIgnoreCase(periodName)).findFirst()
                    .orElse(null);
            if (period == null) {
                throw new InvalidSheetException("Line " + (i + 1) + ": No such period: " + periodName);
            }
            String amount = fields[2].trim();
            if (!amount.matches("\\d+\\.\\d{2}")) {
                throw new InvalidSheetException("Line " + (i + 1) + ": The amount must be 0.00 or more, with two decimals");
            }
            openings.add(new OpeningLine(person, period.name(), new BigDecimal(amount)));
        }
        if (openings.isEmpty()) {
            throw new InvalidSheetException("Paste at least one line of name,period,amount");
        }
        imported.set(new OpeningImportInput(openings, user));
    }
}

